const fs = require("fs");
let pub = "";
let folders = [];
let findFilesResult = [];
const configStore = {}; // e.g. { extraRoots: [...] }
let warningHandler = null; // (message, options, ...buttons) => answer or Promise
const warnings = [];
module.exports = {
  workspace: {
    getConfiguration: () => ({
      get: (k, d) => {
        if (k === "licensePublicKey") return pub;
        return k in configStore ? configStore[k] : d;
      },
      update: async (k, v, _global) => { configStore[k] = v; },
    }),
    get workspaceFolders() { return folders; },
    // Canned result list for search/find tests; set with __setFindFiles.
    findFiles: async () => findFilesResult,
    // Real-filesystem backed, so read/search/list tools run against a temp
    // workspace directory the test creates.
    fs: {
      stat: async (uri) => {
        const s = fs.statSync(uri.fsPath);
        return { size: s.size, type: s.isDirectory() ? 2 : 1 };
      },
      readFile: async (uri) => fs.readFileSync(uri.fsPath),
      readDirectory: async (uri) =>
        fs.readdirSync(uri.fsPath, { withFileTypes: true }).map((d) => [d.name, d.isDirectory() ? 2 : 1]),
    },
  },
  window: {
    showWarningMessage: (message, options, ...buttons) => {
      warnings.push({ message, options, buttons });
      return Promise.resolve(warningHandler ? warningHandler(message, options, ...buttons) : undefined);
    },
  },
  Uri: { file: (p) => ({ fsPath: p }) },
  FileType: { File: 1, Directory: 2, SymbolicLink: 64 },
  Position: class { constructor(line, character) { this.line = line; this.character = character; } },
  Range: class { constructor(start, end) { this.start = start; this.end = end; } },
  WorkspaceEdit: class {
    replace() {}
    insert() {}
    createFile() {}
    deleteFile() {}
    renameFile() {}
  },
  __setPub: (p) => { pub = p; },
  __setFolders: (f) => { folders = f; },
  __setFindFiles: (list) => { findFilesResult = list; },
  __config: configStore,
  __setWarningHandler: (h) => { warningHandler = h; },
  __warnings: warnings,
};
